export const JOOSIE=Object.freeze({name:'Joosie Smollett',special:'Tag-Team Ambush',kind:'joosieAssist',duration:2.6,range:900,color:'#ffcf68',glow:'rgba(255,195,70,.4)'});
const strikes=[.85,1.15,1.45,1.75,2.05];
export function createJoosieSpecial(a){return {kind:JOOSIE.kind,owner:a.id,facing:a.facing,originX:a.x,x:a.x,age:0,ttl:JOOSIE.duration,duration:JOOSIE.duration,active:true,delay:0,hitCount:0,strikeIndex:0};}
export function endJoosieSpecial(g,a,s){s.active=false;s.ttl=0;if(a){a.vx=0;a.actionRemaining=0;g.setState(a,a.hp>0?'idle':'ko');}}
export function updateJoosieSpecial(g,s,a,b){if(!a||!b){endJoosieSpecial(g,a,s);return;}a.facing=s.facing;a.vx=0;if(s.ttl>1e-9){a.state='special';a.actionRemaining=Math.max(a.actionRemaining,s.ttl);}while(s.strikeIndex<strikes.length&&s.age>=strikes[s.strikeIndex]){const i=s.strikeIndex++;const dx=(b.x-s.originX)*s.facing;if(dx>=-35&&dx<=JOOSIE.range&&b.y<185&&g.hit(a,b,9,s.kind,i===4?300:0,.18,b.x-s.facing))s.hitCount++;}if(s.ttl<=1e-9)endJoosieSpecial(g,a,s);}
export function joosiePose(f,s){const t=Math.max(0,f.stateTime||0),p=Math.min(1,Math.max(0,f.attackProgress||0));let index=0;if(f.state==='special')index=(s?.age??t)<.5?18:(s?.age??t)<2.3?19:0;else if(f.state==='punch')index=p<.22?12:p<.78?13:0;else if(f.state==='kick')index=p<.22?8:p<.78?14:0;else if(f.state==='ko')index=16;else if(f.state==='hurt'||f.state==='grabbed'||f.state==='beltHeld')index=15;else if(f.state==='block')index=8;else if(!f.grounded||f.state==='jump'||f.state==='fall')index=t<.08?8:(f.vy??0)>0?9:10;else if(f.joosieLandRemaining>0&&f.state==='idle')index=11;else if(f.state==='recover')index=17;else if(f.state==='run'||f.state==='walk')index=[2,3,4,5][Math.floor(t*9)%4];else index=Math.floor(t*2)%2;return {key:'joosie',index};}
export function drawJoosieAssists(ctx,s,g,ground,draw){const b=g.fighters.find(f=>f.id!==s.owner);if(!b||s.age<.35||s.age>2.45)return;const q=Math.min(1,(s.age-.35)/.5),punch=s.age>=.85&&s.age<2.22&&Math.floor((s.age-.85)*10)%3!==2;const fade=Math.min(1,(s.age-.35)*12,(2.45-s.age)*8);ctx.save();ctx.globalAlpha=Math.max(0,fade);draw(punch?21:20,b.x-75-(1-q)*340,ground-b.y,1,1.1);draw(punch?23:22,b.x+75+(1-q)*340,ground-b.y,-1,1.1);if(s.age>=.78&&s.age<=1.55){ctx.fillStyle='#fff';ctx.strokeStyle='#16131c';ctx.lineWidth=3;ctx.beginPath();ctx.roundRect(b.x-57,ground-b.y-265,114,39,12);ctx.fill();ctx.stroke();ctx.fillStyle='#b31921';ctx.textAlign='center';ctx.font='bold 23px sans-serif';ctx.fillText('MAGA!',b.x,ground-b.y-239);}ctx.restore();}
